# Try making the asymmetric rows symmetric by mirroring
def make_symmetric(grid):
    result = [row[:] for row in grid]
    for i in range(len(grid)):
        # Take right half, reverse it, put on left
        half = grid[i][8:]  # last 8 columns
        rev_half = list(reversed(half))
        # Replace first 8 columns with reversed right half
        for j in range(8):
            result[i][j] = rev_half[j]
    return result

symmetric_grid = make_symmetric(input_grid)
print("Making rows 8-11 symmetric:")
for i in range(8, 12):
    print(f"Row {i}: {symmetric_grid[i]}")

