# Fix vertical symmetry - replace 3s with their vertical mirror values
def fix_grid(grid):
    result = [row[:] for row in grid]
    rows = len(result)
    for i in range(rows):
        j_mirror = rows - 1 - i
        if result[i] != result[j_mirror]:
            # Find positions where result[i][j] is 3 and result[j_mirror][j] is not
            for col in range(16):
                if result[i][col] == 3 and result[j_mirror][col] != 3:
                    result[i][col] = result[j_mirror][col]
    return result

fixed_grid = fix_grid(input_grid)
print("After fixing both directions:")
for i in range(8, 12):
    print(f"Row {i}: {fixed_grid[i]}")

for i in range(4, 8):
